INSERT INTO cases (id, farmer_id, farm_id, farmer_name, crop_type, variety, location, latitude, longitude, field_area, crop_stage, symptoms, image_url, disease, scientific_name, confidence, severity, status, spread_risk, language, weather_context, nearby_alerts, treatment_steps, prevention_steps, affected_area, estimated_loss, officer_id, officer_notes, escalation_reason, officer_verified, verified_disease, verified_severity, verified_at, verified_by, created_at, updated_at) VALUES
('CASE-001', 1, 1, 'Ruwan Perera', 'Paddy (Rice)', 'Samba', 'Ampara, Eastern Province', 7.2912, 81.6724, '1.2 acres', 'Tillering / Vegetative', 'Diamond-shaped lesions with gray centers on leaves, brownish margins, neck rot visible', 'https://images.unsplash.com/photo-1530507629858-e4977d30e9e0?w=800', 'Blast Disease', 'Magnaporthe oryzae', 94, 'high', 'confirmed', 78, 'en', '{"humidity": 87, "temp": 28, "rainfall": 12}'::jsonb, 3, '["Remove and destroy severely infected plant parts immediately", "Apply Tricyclazole (Beam) @ 0.6g/L or Isoprothiolane (Fuji-One) @ 1.5ml/L", "Ensure proper field drainage to reduce humidity", "Avoid excessive nitrogen application", "Monitor neighboring fields and alert farmers within 2km radius"]'::jsonb, '["Plant certified resistant cultivars (Bg 358, Bg 379/2)", "Maintain balanced fertilization with split potassium doses", "Avoid late-season planting when morning dew duration exceeds 8 hours"]'::jsonb, '0.8 acres', '35%', 2, 'Field symptoms match typical blast lesions. Spore count accelerated by recent morning dew. Approved application of systemic fungicide.', NULL, true, 'Blast Disease', 'high', NOW() - INTERVAL '4 hours', 2, NOW() - INTERVAL '1 day', NOW() - INTERVAL '4 hours'),
('CASE-002', 1, 2, 'Ruwan Perera', 'Tea', 'TRI-2043', 'Nuwara Eliya, Central Province', 6.9497, 80.7891, '1.5 acres', 'Flushing', 'Pale green translucent spots on young leaves, white powdery growth on underside', 'https://images.unsplash.com/photo-1588668214407-6ea9a6d8c272?w=800', 'Blister Blight', 'Exobasidium vexans', 89, 'medium', 'escalated', 62, 'en', '{"humidity": 92, "temp": 18, "rainfall": 28}'::jsonb, 1, '["Apply copper-based fungicides (Copper oxychloride) at 2.5g/L", "Improve air circulation by proper pruning", "Avoid working in wet conditions to prevent spread", "Apply systemic fungicide Hexaconazole @ 2ml/10L"]'::jsonb, '["Regulate shade trees to allow morning sun penetration", "Prune bushes on correct schedule", "Harvest tender flush systematically"]'::jsonb, '1.2 acres', '20%', NULL, NULL, 'Unusually fast spread on tender flush leaves despite initial copper oxychloride spray. Need field inspection.', false, NULL, NULL, NULL, NULL, NOW() - INTERVAL '2 days', NOW() - INTERVAL '1 day'),
('CASE-003', 5, 3, 'Chamara Bandara', 'Maize (Corn)', 'NK-6240', 'Kurunegala, North Western Province', 7.4863, 80.3623, '3.5 acres', 'Whorl Stage', 'Ragged holes in leaves, frass in whorls, irregular window feeding on leaves', 'https://images.unsplash.com/photo-1551893478-d726eaf0442c?w=800', 'Fall Armyworm', 'Spodoptera frugiperda', 97, 'critical', 'pending', 91, 'en', '{"humidity": 75, "temp": 32, "rainfall": 0}'::jsonb, 4, '["Apply Emamectin benzoate (Proclaim) @ 0.4g/L immediately into whorls", "Use Spinetoram (Delegate) @ 0.5ml/L for effective second-generation control", "Set up pheromone traps (5 per acre) for continuous monitoring", "Alert neighboring maize farmers within 5km radius", "Conduct scouting every 3 days"]'::jsonb, '["Synchronized planting across adjacent blocks", "Intercrop with non-host pulses", "Handpick egg masses and young larvae during early whorl stage"]'::jsonb, '3.5 acres', '60%', NULL, NULL, 'Critical pest severity detected automatically by AI.', false, NULL, NULL, NULL, NULL, NOW() - INTERVAL '6 hours', NOW() - INTERVAL '6 hours'),
('CASE-004', 6, 4, 'Priya Jayawardena', 'Coconut', 'Sri Lanka Tall', 'Puttalam, North Western Province', 8.0362, 79.8283, '5.0 acres', 'Bearing', 'Yellowing of lower fronds, premature nut fall, reduction in inflorescences', 'https://images.unsplash.com/photo-1598880940371-c756e015fea1?w=800', 'Weligama Coconut Leaf Wilt', 'Phytoplasma sp.', 71, 'high', 'escalated', 85, 'en', '{"humidity": 80, "temp": 30, "rainfall": 5}'::jsonb, 2, '["Remove and burn all infected palms immediately", "Apply oxytetracycline injections to early-stage infected palms", "Control insect vectors (leafhopper) using insecticides", "Quarantine the affected area", "Report to Coconut Cultivation Board immediately"]'::jsonb, '["Plant vector-tolerant coconut varieties", "Regular weed sanitation to suppress vector habitats", "Strict quarantine on transport of planting material"]'::jsonb, '5 acres', '45%', 2, NULL, 'Low AI confidence (71%) on leaf wilt. Automatically escalated for field officer validation.', false, NULL, NULL, NULL, NULL, NOW() - INTERVAL '3 days', NOW() - INTERVAL '2 days'),
('CASE-005', 1, 5, 'Ruwan Perera', 'Tomato', 'Thilina', 'Badulla, Uva Province', 6.9934, 81.0550, '0.5 acres', 'Flowering & Fruiting', 'Water-soaked lesions on leaves, white mold on undersides, brown stem lesions', 'https://images.unsplash.com/photo-1592841200221-a6898f307baa?w=800', 'Late Blight', 'Phytophthora infestans', 91, 'high', 'treated', 45, 'en', '{"humidity": 90, "temp": 22, "rainfall": 18}'::jsonb, 1, '["Apply Metalaxyl + Mancozeb (Ridomil Gold) @ 2.5g/L", "Remove affected plant material and dispose properly", "Improve drainage and reduce leaf wetness", "Apply preventive copper sprays every 7 days"]'::jsonb, '["Avoid overhead irrigation", "Stake plants and mulch soil", "Rotate with non-solanaceous crops"]'::jsonb, '0.5 acres', '25%', 2, 'Farmer completed spray protocol on Sep 9. Spot necrosis arrested.', NULL, true, 'Late Blight', 'high', NOW() - INTERVAL '3 days', 2, NOW() - INTERVAL '4 days', NOW() - INTERVAL '3 days'),
('CASE-006', 10, 6, 'Sunil Jayasuriya', 'Paddy (Rice)', 'Bg 358', 'Ampara East, Eastern Province', 7.3050, 81.6810, '3.0 acres', 'Tillering', 'Spindle-shaped brown lesions with gray centers spreading rapidly across leaf blades', 'https://images.unsplash.com/photo-1530507629858-e4977d30e9e0?w=800', 'Blast Disease', 'Magnaporthe oryzae', 92, 'high', 'confirmed', 82, 'en', '{"humidity": 88, "temp": 28, "rainfall": 15}'::jsonb, 3, '["Apply Tricyclazole @ 0.6g/L immediately", "Drain stagnant water from paddy bunds", "Suspend nitrogen top dressing"]'::jsonb, '["Plant resistant varieties", "Maintain wide spacing for air ventilation"]'::jsonb, '1.5 acres', '30%', 2, 'Matches neighboring CASE-001 spore propagation pattern. Confirmed.', NULL, true, 'Blast Disease', 'high', NOW() - INTERVAL '12 hours', 2, NOW() - INTERVAL '18 hours', NOW() - INTERVAL '12 hours'),
('CASE-007', 11, 7, 'Kithsiri Gamage', 'Paddy (Rice)', 'At 362', 'Digamadulla, Eastern Province', 7.3200, 81.6950, '4.2 acres', 'Panicle Initiation', 'Brownish necrotic lesions on flag leaves, neck blast symptoms emerging', 'https://images.unsplash.com/photo-1530507629858-e4977d30e9e0?w=800', 'Blast Disease', 'Magnaporthe oryzae', 95, 'critical', 'confirmed', 88, 'en', '{"humidity": 89, "temp": 27, "rainfall": 18}'::jsonb, 3, '["Urgent application of Isoprothiolane @ 1.5ml/L", "Create buffer isolation strip around affected blocks", "Alert regional extension center"]'::jsonb, '["Treat seeds with carbendazim prior to sowing", "Avoid late season nitrogen application"]'::jsonb, '2.0 acres', '45%', 2, 'Third confirmed blast case in 5km corridor. Urgent outbreak response triggered.', NULL, true, 'Blast Disease', 'critical', NOW() - INTERVAL '5 hours', 2, NOW() - INTERVAL '8 hours', NOW() - INTERVAL '5 hours')
