('VISIT-002', 'CASE-003', 5, 2, 'Chamara Bandara', 'Kurunegala, NW Province', 'Maize', CURRENT_DATE - INTERVAL '1 day', 'completed', 'critical', 'Fall armyworm pheromone traps deployed successfully.', 'Larval frass in 40% of whorls inspected. First instar larvae confirmed.', 'Fall Armyworm', 'critical', 'Deploy synchronized Emamectin benzoate application across 3 adjacent farms.', NOW() - INTERVAL '1 day'),
('VISIT-003', 'CASE-004', 6, 2, 'Priya Jayawardena', 'Puttalam, NW Province', 'Coconut', CURRENT_DATE + INTERVAL '3 days', 'scheduled', 'high', 'Assess Weligama leaf wilt symptom spread and vector management protocol.', NULL, NULL, NULL, NULL, NULL),
('VISIT-004', 'CASE-007', 11, 2, 'Kithsiri Gamage', 'Digamadulla, Eastern Province', 'Paddy (Rice)', CURRENT_DATE - INTERVAL '3 hours', 'completed', 'critical', 'Emergency cluster verification for Ampara Rice Belt.', 'Neck blast sporulation visible on 30% of hills. Severe leaf necrosis.', 'Blast Disease', 'critical', 'Quarantine block 3, initiate aerial spray buffer, alert all farms within 10km.', NOW() - INTERVAL '3 hours')
